#nullable enable // autogenerated

using System;
using MVZ2.Level.Inputing;
using MVZ2.UI;
using MVZ2Logic.Inputs;
using PVZEngine.Tools.Unity;
using UnityEngine;
using UnityEngine.EventSystems;

namespace MVZ2.Blueprints
{
    public class BlueprintDisplayerStandalonePage : MonoBehaviour
    {
        public void UpdateItems(ChoosingBlueprintViewData[] viewDatas)
        {
            blueprintList.updateList(viewDatas.Length, (i, rect) =>
            {
                var blueprint = rect.GetComponent<Blueprint>();
                blueprint.UpdateView(viewDatas[i].blueprint);
                blueprint.SetDisabled(viewDatas[i].disabled);
                blueprint.SetSelected(viewDatas[i].selected);
                blueprint.SetRecharge(viewDatas[i].recharge);
            },
            rect =>
            {
                var blueprint = rect.GetComponent<Blueprint>();
                blueprint.OnPointerInteraction += OnBlueprintPointerInteractionCallback;
                blueprint.OnSelect += OnBlueprintSelectCallback;
            },
            rect =>
            {
                var blueprint = rect.GetComponent<Blueprint>();
                blueprint.OnPointerInteraction -= OnBlueprintPointerInteractionCallback;
                blueprint.OnSelect -= OnBlueprintSelectCallback;
            });
        }
        public Blueprint? GetItem(int index)
        {
            return blueprintList.getElement<Blueprint>(index);
        }
        private void OnBlueprintPointerInteractionCallback(Blueprint blueprint, PointerInteractionArgs args)
        {
            OnBlueprintPointerInteraction?.Invoke(this, blueprintList.indexOf(blueprint), args);
        }
        private void OnBlueprintSelectCallback(Blueprint blueprint, PointerInteractionArgs args)
        {
            OnBlueprintSelect?.Invoke(this, blueprintList.indexOf(blueprint), args);
        }
        public event Action<BlueprintDisplayerStandalonePage, int, PointerInteractionArgs>? OnBlueprintPointerInteraction;
        public event Action<BlueprintDisplayerStandalonePage, int, PointerInteractionArgs>? OnBlueprintSelect;
        [SerializeField]
        ElementListUI blueprintList = null!;
    }
}
